CREATE TYPE public.app_role AS ENUM ('rep','rd','sd','ceo');
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, active boolean NOT NULL DEFAULT true);
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
REVOKE UPDATE ON public.profiles FROM authenticated; GRANT UPDATE(display_name,avatar_url) ON public.profiles TO authenticated;
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(new.id,coalesce(new.raw_user_meta_data->>'display_name','')); RETURN new; END; $$;
CREATE TRIGGER milkontrol_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.regions(id integer PRIMARY KEY,name text NOT NULL,latitude numeric,longitude numeric,demo boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.regions TO anon,authenticated; GRANT ALL ON public.regions TO service_role; ALTER TABLE public.regions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.employees(id integer PRIMARY KEY,name text NOT NULL,region_id integer NOT NULL REFERENCES public.regions(id),photo_discipline numeric NOT NULL DEFAULT 0,demo boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.employees TO anon,authenticated; GRANT ALL ON public.employees TO service_role; ALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL,region_id integer REFERENCES public.regions(id),employee_id integer REFERENCES public.employees(id),UNIQUE(user_id,role),CHECK(role<>'rd' OR region_id IS NOT NULL),CHECK(role<>'rep' OR employee_id IS NOT NULL));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.can_scope(r integer,e integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles u JOIN public.profiles p ON p.id=u.user_id WHERE u.user_id=auth.uid() AND p.active AND (u.role IN ('sd','ceo') OR (u.role='rd' AND u.region_id=r) OR (u.role='rep' AND u.employee_id=e))); $$;
CREATE FUNCTION public.is_manager(r integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles u JOIN public.profiles p ON p.id=u.user_id WHERE u.user_id=auth.uid() AND p.active AND (u.role IN ('sd','ceo') OR (u.role='rd' AND u.region_id=r))); $$;
CREATE POLICY region_demo ON public.regions FOR SELECT USING(demo OR public.can_scope(id,null));
CREATE POLICY employee_demo_anon ON public.employees FOR SELECT TO anon USING(demo);
CREATE POLICY employee_scope ON public.employees FOR SELECT TO authenticated USING(public.can_scope(region_id,id));
CREATE TABLE public.retail_outlets(id integer PRIMARY KEY,name text NOT NULL,address text NOT NULL DEFAULT 'Demo address — confirmation required',region_id integer NOT NULL REFERENCES public.regions(id),employee_id integer NOT NULL REFERENCES public.employees(id),latitude numeric,longitude numeric,coordinates_verified boolean NOT NULL DEFAULT false,demo boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.retail_outlets TO anon,authenticated; GRANT ALL ON public.retail_outlets TO service_role; ALTER TABLE public.retail_outlets ENABLE ROW LEVEL SECURITY;
CREATE POLICY outlet_demo ON public.retail_outlets FOR SELECT TO anon USING(demo); CREATE POLICY outlet_scope ON public.retail_outlets FOR SELECT TO authenticated USING(public.can_scope(region_id,employee_id));
CREATE TABLE public.sales_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),outlet_id integer NOT NULL REFERENCES public.retail_outlets(id),period date NOT NULL,amount numeric NOT NULL CHECK(amount>=0),plan numeric NOT NULL CHECK(plan>=0),UNIQUE(outlet_id,period));
GRANT SELECT ON public.sales_records TO anon,authenticated; GRANT ALL ON public.sales_records TO service_role; ALTER TABLE public.sales_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY sales_read ON public.sales_records FOR SELECT USING(EXISTS(SELECT 1 FROM public.retail_outlets o WHERE o.id=outlet_id));
CREATE TABLE public.equipment(id text PRIMARY KEY,outlet_id integer NOT NULL UNIQUE REFERENCES public.retail_outlets(id),status text NOT NULL CHECK(status IN ('installed','missing','under_inspection','not_verified')),last_verified_at timestamptz,expected boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.equipment TO anon,authenticated; GRANT ALL ON public.equipment TO service_role; ALTER TABLE public.equipment ENABLE ROW LEVEL SECURITY;
CREATE POLICY equipment_read ON public.equipment FOR SELECT USING(EXISTS(SELECT 1 FROM public.retail_outlets o WHERE o.id=outlet_id));
CREATE TABLE public.planned_visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),outlet_id integer NOT NULL REFERENCES public.retail_outlets(id),scheduled_at timestamptz NOT NULL,completed_at timestamptz);
GRANT SELECT ON public.planned_visits TO anon,authenticated; GRANT ALL ON public.planned_visits TO service_role; ALTER TABLE public.planned_visits ENABLE ROW LEVEL SECURITY;
CREATE POLICY plan_read ON public.planned_visits FOR SELECT USING(EXISTS(SELECT 1 FROM public.retail_outlets o WHERE o.id=outlet_id));
CREATE TABLE public.visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),outlet_id integer NOT NULL REFERENCES public.retail_outlets(id),user_id uuid NOT NULL,latitude numeric NOT NULL,longitude numeric NOT NULL,accuracy numeric NOT NULL,verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),checklist jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.visits TO authenticated; GRANT ALL ON public.visits TO service_role; ALTER TABLE public.visits ENABLE ROW LEVEL SECURITY;
CREATE POLICY visit_scope ON public.visits FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.retail_outlets o WHERE o.id=outlet_id));
CREATE TABLE public.alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),condition_key text NOT NULL UNIQUE,kind text NOT NULL,title text NOT NULL,priority text NOT NULL CHECK(priority IN ('critical','high','medium')),region_id integer NOT NULL REFERENCES public.regions(id),employee_id integer NOT NULL REFERENCES public.employees(id),outlet_id integer REFERENCES public.retail_outlets(id),evidence jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'detected',detected_at timestamptz NOT NULL DEFAULT now(),demo boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.alerts TO anon,authenticated; GRANT ALL ON public.alerts TO service_role; ALTER TABLE public.alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY alert_demo ON public.alerts FOR SELECT TO anon USING(demo); CREATE POLICY alert_scope ON public.alerts FOR SELECT TO authenticated USING(public.can_scope(region_id,employee_id));
CREATE TABLE public.tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),alert_id uuid NOT NULL UNIQUE REFERENCES public.alerts(id),assigned_employee_id integer NOT NULL REFERENCES public.employees(id),deadline timestamptz NOT NULL,status text NOT NULL DEFAULT 'assigned' CHECK(status IN ('assigned','in_progress','awaiting_verification','resolved','rejected','reopened')),resolution text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.tasks TO authenticated; GRANT ALL ON public.tasks TO service_role; ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY task_scope ON public.tasks FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.alerts a WHERE a.id=alert_id));
CREATE TABLE public.task_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL REFERENCES public.tasks(id),user_id uuid NOT NULL,action text NOT NULL,comment text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.task_events TO authenticated; GRANT ALL ON public.task_events TO service_role; ALTER TABLE public.task_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_scope ON public.task_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=task_id));
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,alert_id uuid NOT NULL REFERENCES public.alerts(id),read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,alert_id));
GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notification_read ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY notification_update ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); REVOKE UPDATE ON public.notifications FROM authenticated; GRANT UPDATE(read_at) ON public.notifications TO authenticated;
CREATE TABLE public.photo_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),outlet_id integer NOT NULL REFERENCES public.retail_outlets(id),visit_id uuid REFERENCES public.visits(id),user_id uuid NOT NULL,storage_path text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),rejection_reason text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.photo_reports TO authenticated; GRANT ALL ON public.photo_reports TO service_role; ALTER TABLE public.photo_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY photo_read ON public.photo_reports FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.retail_outlets o WHERE o.id=outlet_id)); CREATE POLICY photo_insert ON public.photo_reports FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending' AND EXISTS(SELECT 1 FROM public.retail_outlets o WHERE o.id=outlet_id) AND storage_path LIKE auth.uid()::text||'/%');
CREATE TABLE public.detection_settings(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1),missed_visits integer NOT NULL DEFAULT 5,sales_drop numeric NOT NULL DEFAULT 30,plan_threshold numeric NOT NULL DEFAULT 50,geofence_meters numeric NOT NULL DEFAULT 150);
GRANT SELECT ON public.detection_settings TO authenticated; GRANT ALL ON public.detection_settings TO service_role; ALTER TABLE public.detection_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY settings_read ON public.detection_settings FOR SELECT TO authenticated USING(true);
CREATE FUNCTION public.detect_problems(target_period date DEFAULT '2026-11-01') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s record; BEGIN SELECT coalesce(max(missed_visits),5) AS misses,coalesce(max(sales_drop),30) AS drop_pct,coalesce(max(plan_threshold),50) AS plan_pct INTO s FROM public.detection_settings;
INSERT INTO public.alerts(condition_key,kind,title,priority,region_id,employee_id,evidence,demo) SELECT 'miss:'||e.id||':'||target_period,'missed_visits','Five planned visits missed','high',e.region_id,e.id,jsonb_build_object('count',count(*),'outlets',jsonb_agg(p.outlet_id),'dates',jsonb_agg(p.scheduled_at)),e.demo FROM public.planned_visits p JOIN public.retail_outlets o ON o.id=p.outlet_id JOIN public.employees e ON e.id=o.employee_id WHERE p.completed_at IS NULL AND p.scheduled_at<now() AND date_trunc('month',p.scheduled_at)::date=target_period GROUP BY e.id HAVING count(*)>=s.misses ON CONFLICT(condition_key) DO NOTHING;
INSERT INTO public.alerts(condition_key,kind,title,priority,region_id,employee_id,evidence,demo) SELECT 'drop:'||e.id||':'||target_period,'sales_drop','Sales decreased by 30% or more','high',e.region_id,e.id,jsonb_build_object('current',sum(c.amount),'previous',sum(p.amount),'change',round((sum(c.amount)/nullif(sum(p.amount),0)-1)*100,2)),e.demo FROM public.employees e JOIN public.retail_outlets o ON o.employee_id=e.id JOIN public.sales_records c ON c.outlet_id=o.id AND c.period=target_period JOIN public.sales_records p ON p.outlet_id=o.id AND p.period=(target_period-interval '1 month')::date GROUP BY e.id HAVING sum(p.amount)>0 AND sum(c.amount)<=sum(p.amount)*(1-s.drop_pct/100) ON CONFLICT(condition_key) DO NOTHING;
INSERT INTO public.alerts(condition_key,kind,title,priority,region_id,employee_id,outlet_id,evidence,demo) SELECT 'missing:'||q.id,'missing_freezer','Company freezer confirmed missing','critical',o.region_id,o.employee_id,o.id,jsonb_build_object('equipment',q.id,'last_verified',q.last_verified_at),o.demo FROM public.equipment q JOIN public.retail_outlets o ON o.id=q.outlet_id WHERE q.expected AND q.status='missing' ON CONFLICT(condition_key) DO NOTHING;
INSERT INTO public.alerts(condition_key,kind,title,priority,region_id,employee_id,outlet_id,evidence,demo) SELECT 'idle:'||q.id||':'||target_period,'freezer_without_sales','Installed freezer has no sales','medium',o.region_id,o.employee_id,o.id,jsonb_build_object('equipment',q.id,'sales',c.amount,'period',target_period),o.demo FROM public.equipment q JOIN public.retail_outlets o ON o.id=q.outlet_id JOIN public.sales_records c ON c.outlet_id=o.id AND c.period=target_period WHERE q.status='installed' AND c.amount=0 ON CONFLICT(condition_key) DO NOTHING;
INSERT INTO public.alerts(condition_key,kind,title,priority,region_id,employee_id,evidence,demo) SELECT 'plan:'||e.id||':'||target_period,'low_plan','Sales plan completion at or below 50%','medium',e.region_id,e.id,jsonb_build_object('current',sum(c.amount),'target',sum(c.plan),'achievement',round(sum(c.amount)/nullif(sum(c.plan),0)*100,2),'gap',sum(c.plan)-sum(c.amount)),e.demo FROM public.employees e JOIN public.retail_outlets o ON o.employee_id=e.id JOIN public.sales_records c ON c.outlet_id=o.id AND c.period=target_period GROUP BY e.id HAVING sum(c.plan)>0 AND sum(c.amount)<=sum(c.plan)*s.plan_pct/100 ON CONFLICT(condition_key) DO NOTHING;
INSERT INTO public.notifications(user_id,alert_id) SELECT u.user_id,a.id FROM public.alerts a JOIN public.user_roles u ON u.role IN ('sd','ceo') OR (u.role='rd' AND u.region_id=a.region_id) WHERE a.status<>'resolved' ON CONFLICT DO NOTHING; END; $$;
REVOKE ALL ON FUNCTION public.detect_problems(date) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.detect_problems(date) TO service_role;
CREATE FUNCTION public.refresh_detection() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.detect_problems('2026-11-01'); RETURN NEW; END; $$;
CREATE TRIGGER sales_detection AFTER INSERT OR UPDATE ON public.sales_records FOR EACH STATEMENT EXECUTE FUNCTION public.refresh_detection();
CREATE TRIGGER equipment_detection AFTER INSERT OR UPDATE ON public.equipment FOR EACH STATEMENT EXECUTE FUNCTION public.refresh_detection();
CREATE TRIGGER planned_detection AFTER INSERT OR UPDATE ON public.planned_visits FOR EACH STATEMENT EXECUTE FUNCTION public.refresh_detection();